show_fit <- function(label, fit) {
 cat(label, "\n", sep="")
 cat("par=",paste(sprintf("%.6f",fit$par),collapse=","),"\n",sep="")
 cat("value=",sprintf("%.8f",fit$value),"\n",sep="")
 cat("counts=",paste(fit$counts,collapse=","),";names=",paste(names(fit$counts),collapse=","),"\n",sep="")
 cat("convergence=",fit$convergence,"\n",sep="")
 if(!is.null(fit$hessian)) cat("hessian=",paste(sprintf("%.4f",fit$hessian),collapse=","),";dim=",paste(dim(fit$hessian),collapse=","),"\n",sep="")
}
rosen <- function(p) 100*(p[2]-p[1]^2)^2+(1-p[1])^2
rosen_gr <- function(p) c(-400*p[1]*(p[2]-p[1]^2)-2*(1-p[1]),200*(p[2]-p[1]^2))
show_fit("rosen-analytic", optim(c(-1.2,1),rosen,rosen_gr,method="BFGS",hessian=TRUE))
show_fit("rosen-analytic-compiled", compiler::cmpfun(function() optim(c(-1.2,1),rosen,rosen_gr,method="BFGS",hessian=TRUE))())
show_fit("rosen-numeric", optim(c(-1.2,1),rosen,method="BFGS",hessian=TRUE))
show_fit("rosen-scaled", optim(c(-1.2,1),rosen,rosen_gr,method="BFGS",control=list(parscale=c(0.5,2),reltol=1e-10),hessian=TRUE))
show_fit("maxit-zero", optim(c(-1.2,1),rosen,rosen_gr,method="BFGS",control=list(maxit=0)))
x<-c(1,2,3,2,1,2,3,2,1)
a<-arima0(x,order=c(1,0,0),method="CSS")
cat("arima0-coef=",paste(round(as.numeric(a$coef),4),collapse=","),"\n",sep="")
cat("arima0-class=",class(a),"\n",sep="")
show_error <- function(label, expr) cat(label,"=",tryCatch({force(expr);"accepted"},error=function(e) conditionMessage(e)),"\n",sep="")
show_error("report-zero",optim(c(-1.2,1),rosen,rosen_gr,method="BFGS",control=list(REPORT=0)))
show_error("initial-infinite",optim(1,function(p) Inf,method="BFGS"))
show_error("initial-na",optim(1,function(p) NA_real_,method="BFGS"))
show_fit("maxit-zero-report-zero",optim(c(-1.2,1),rosen,rosen_gr,method="BFGS",control=list(maxit=0,REPORT=0)))
